"""Split documentation pages into retrievable chunks."""

import re
from typing import Any, Dict, List, Mapping, Optional

import numpy as np
from pydantic import BaseModel, ConfigDict, Field

from rasa.builder.document_retrieval.local.config import ChunkingConfig
from rasa.builder.document_retrieval.source import SourceDocument

# Rough English approximation used to convert token budgets to word counts,
# avoiding a tokenizer dependency.
TOKENS_PER_WORD = 0.75

# Matches a line that is a markdown h1-h3 heading.
_HEADING_RE = re.compile(r"^#{1,3}(?:\s|$)")
# Matches a line that opens or closes a fenced code block. Leading whitespace is
# allowed because MDX pages indent code blocks nested inside components.
_FENCE_RE = re.compile(r"^\s*(`{3,}|~{3,})")


def _heading_offsets(text: str) -> List[int]:
    """Return where each h1-h3 heading line starts, skipping fenced code blocks.

    Lines inside a fence, such as YAML or shell comments, or prompt templates
    with markdown headings, are content rather than section boundaries. A
    fence closes on a line of the same character that is at least as long, so
    a shorter fence nested in a longer one doesn't close it; an unclosed fence
    runs to the end of the text.
    """
    offsets: List[int] = []
    fence: Optional[str] = None
    offset = 0
    for line in text.split("\n"):
        fence_match = _FENCE_RE.match(line)
        if fence is None:
            if fence_match:
                fence = fence_match.group(1)
            elif _HEADING_RE.match(line):
                offsets.append(offset)
        elif (
            fence_match
            and fence_match.group(1)[0] == fence[0]
            and len(fence_match.group(1)) >= len(fence)
            and not line[fence_match.end() :].strip()
        ):
            fence = None
        offset += len(line) + 1
    return offsets


class Chunk(BaseModel):
    """A single retrievable chunk carrying its source-document provenance.

    Its fields are the columns of every stored chunk row: the build rows, the
    parquet artifact and the vector store all derive their columns from it.
    """

    model_config = ConfigDict(frozen=True)

    text: str
    doc_id: str
    url: str
    title: str
    topic: str
    version: str = Field(
        default="",
        description="Source document version/hash; used for incremental sync.",
    )
    chunk_index: int = Field(
        description="Sequential index of the chunk within the document."
    )

    def to_row(self, vector: np.ndarray) -> Dict[str, Any]:
        """Return the stored row: the vector first, then every chunk field."""
        return {"vector": vector, **self.model_dump()}

    @classmethod
    def from_row(cls, row: Mapping[str, Any]) -> "Chunk":
        """Rebuild a chunk from a stored row, ignoring vector and score columns."""
        return cls.model_validate({name: row[name] for name in cls.model_fields})


class Chunker:
    """Splits a :class:`SourceDocument` into :class:`Chunk` objects by heading."""

    def __init__(self, config: ChunkingConfig) -> None:
        self._config = config

    def chunk_document(self, document: SourceDocument, topic: str) -> List[Chunk]:
        """Split a document into one chunk per h1-h3 section.

        Blank chunks are dropped, and so are repeats of a chunk already produced
        for this document (a changelog repeats the same boilerplate section per
        release). First occurrences keep their order, so ``chunk_index`` stays
        contiguous. Identical chunks on different documents are all kept.
        """
        texts = self._by_heading(document.content, document.title)
        unique_texts = dict.fromkeys(text for text in texts if text.strip())
        return [
            Chunk(
                text=text,
                doc_id=document.id,
                url=document.url or "",
                title=document.title,
                topic=topic,
                version=document.version or "",
                chunk_index=i,
            )
            for i, text in enumerate(unique_texts)
        ]

    def _fixed_token(self, text: str) -> List[str]:
        """Sliding word-window split approximating a token budget."""
        words = text.split()
        if not words:
            return []
        per_chunk = max(1, round(self._config.chunk_size * TOKENS_PER_WORD))
        overlap = max(0, round(self._config.chunk_overlap * TOKENS_PER_WORD))
        step = max(1, per_chunk - overlap)
        return [" ".join(words[i : i + per_chunk]) for i in range(0, len(words), step)]

    def _by_heading(self, text: str, title: str) -> List[str]:
        """Split at h1-h3 boundaries, keeping the heading and page title in-chunk.

        Headings inside fenced code blocks don't split. Oversized sections fall
        back to the fixed-token splitter. Small-section merging is intentionally
        skipped (known refinement, not needed for POC).
        """
        starts = _heading_offsets(text)

        sections: List[str] = []
        if not starts:
            sections.append(text.strip())
        else:
            if starts[0] > 0:  # preamble before the first heading
                sections.append(text[: starts[0]].strip())
            for i, start in enumerate(starts):
                end = starts[i + 1] if i + 1 < len(starts) else len(text)
                sections.append(text[start:end].strip())

        max_words = round(self._config.chunk_size / TOKENS_PER_WORD)
        chunks: List[str] = []
        for section in filter(None, sections):
            if len(section.split()) > max_words:
                heading = section.splitlines()[0]
                for piece in self._fixed_token(section):
                    chunks.append(f"{title}\n{heading}\n{piece}")
            else:
                chunks.append(f"{title}\n{section}")
        return chunks
